import { useCallback, useEffect, useMemo, useState } from "react";

interface NativePanelProps { installId: number; projectId: string }
interface Agent { id:number; name:string; status:string; directive?:string; directive_etag?:string }
interface Model { gateway_model?:string; display_name?:string; provider?:string; model_id?:string }
interface Environment { id:string; name:string }
interface Target { agent_id:number; agent_name?:string; model?:string; provider?:string }
interface Assertion { name:string; type:string; app?:string; tool?:string; input?:Record<string,any>; path?:string; equals?:any; method?:string; host?:string; min_calls?:number; agent_alias?:string; event_type?:string }
interface EvalCase { id:string; suite_id:string; name:string; prompt:string; goals:string[]; assertions:Assertion[]; environment_id?:string; timeout_seconds:number; max_turns:number; enabled:boolean; revision:number }
interface Suite { id:string; name:string; description?:string; environment_id?:string; judge_model?:string; continuous_targets?:Target[]; schedule_minutes:number; required_pass_rate:number; enabled:boolean; revision:number; cases:EvalCase[] }
interface Metrics { provider?:string; model?:string; llm_calls:number; tokens_in:number; tokens_out:number; cost_usd:number; tool_calls:number; errors:number }
interface TraceEvent { index:number; role:string; content?:string; tool_call?:{name:string;input?:any;output?:string;is_error?:boolean} }
interface EvalRun { id:string; case_id:string; status:string; target_index:number; repetition:number; case:EvalCase; target:Target; overall_score?:number; correctness_score?:number; judge_score?:number; error?:string; assertions:any[]; suggestions?:{id:string;directive:string;reason:string;status:string}[]; execution?:{status:string;reason:string;turns:number;trace:TraceEvent[];metrics:Metrics}; judge?:{passed:boolean;score:number;reasoning:string;per_goal:any[]} }
interface TargetSummary { target_index:number; target:Target; runs:number; passed:number; pass_rate:number; average_score:number; average_cost_usd:number; average_tokens:number }
interface Summary { total:number; queued:number; running:number; passed:number; failed:number; errors:number; pass_rate:number; average_score:number; targets:TargetSummary[] }
interface Experiment { id:string; suite_id:string; name:string; trigger_type:string; status:string; targets:Target[]; repetitions:number; judge_model?:string; created_at:string; finished_at?:string; summary?:Summary; runs?:EvalRun[] }
interface Catalog { agents:Agent[]; models:Model[]; environments:Environment[] }

const API="/api/apps/evals/api";let installID=0;let projectID="";
async function request<T>(path:string,init?:RequestInit):Promise<T>{const url=new URL(API+path,window.location.origin);if(installID)url.searchParams.set("install_id",String(installID));if(projectID)url.searchParams.set("project_id",projectID);const response=await fetch(url.pathname+url.search,{...init,headers:{"Content-Type":"application/json",...(init?.headers||{})}});if(!response.ok){const body=await response.json().catch(()=>({error:response.statusText}));throw new Error(body.error||response.statusText)}return response.json()}
const modelID=(model:Model)=>model.gateway_model||`${model.provider||""}/${model.model_id||""}`.replace(/^\//,"");
const pct=(value:number)=>`${Math.round((value||0)*100)}%`;const score=(value?:number)=>value==null?"—":String(Math.round(value));

function Status({value}:{value:string}){const tone=value==="pass"||value==="completed"?"text-green":value==="fail"||value==="error"?"text-red":value==="running"?"text-accent":"text-text-dim";return <span className={`text-xs font-semibold ${tone}`}>{value}</span>}
function Empty({children}:{children:any}){return <div className="p-10 text-center text-sm text-text-dim">{children}</div>}
function Metric({label,value,detail}:{label:string;value:string;detail?:string}){return <div className="min-w-0 border-r border-border px-4 py-3 last:border-r-0"><span className="block text-[11px] font-semibold uppercase text-text-dim">{label}</span><span className="mt-1 block truncate text-lg font-semibold text-text">{value}</span>{detail&&<span className="block truncate text-xs text-text-dim">{detail}</span>}</div>}

function SearchSelect<T>({placeholder,items,label,onSelect}:{placeholder:string;items:T[];label:(x:T)=>string;onSelect:(x:T)=>void}){const [query,setQuery]=useState("");const shown=useMemo(()=>query?items.filter(x=>label(x).toLowerCase().includes(query.toLowerCase())).slice(0,8):[],[query,items]);return <div className="relative"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder} className="w-full rounded-md border border-border bg-bg-card px-3 py-2 text-sm outline-none focus:border-accent"/>{shown.length>0&&<div className="absolute z-20 mt-1 max-h-56 w-full overflow-auto rounded-md border border-border bg-bg shadow-xl">{shown.map((item,i)=><button key={i} onClick={()=>{onSelect(item);setQuery("")}} className="block w-full border-b border-border px-3 py-2 text-left text-sm last:border-0 hover:bg-bg-hover">{label(item)}</button>)}</div>}</div>}
function Chip({children,onRemove}:{children:any;onRemove:()=>void}){return <span className="inline-flex max-w-full items-center gap-1.5 rounded border border-border bg-bg-card px-2 py-1 text-xs"><span className="truncate">{children}</span><button onClick={onRemove} title="Remove" className="text-text-dim hover:text-red">×</button></span>}

function ExperimentBuilder({suites,catalog,initialSuiteID,onClose,onCreated}:{suites:Suite[];catalog:Catalog;initialSuiteID?:string;onClose:()=>void;onCreated:(x:Experiment)=>void}){const initialSuite=suites.find(x=>x.id===initialSuiteID)||suites[0];const [suiteID,setSuiteID]=useState(initialSuite?.id||"");const [targets,setTargets]=useState<Target[]>([]);const [selectedAgent,setSelectedAgent]=useState<Agent|null>(null);const [repetitions,setRepetitions]=useState(1);const [judgeModel,setJudgeModel]=useState(initialSuite?.judge_model||"");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const addModel=(model:Model)=>{if(!selectedAgent)return;const id=modelID(model);if(targets.some(x=>x.agent_id===selectedAgent.id&&x.model===id))return;setTargets([...targets,{agent_id:selectedAgent.id,agent_name:selectedAgent.name,model:id}])};const create=async()=>{setBusy(true);try{const value=await request<Experiment>("/experiments",{method:"POST",body:JSON.stringify({suite_id:suiteID,targets,repetitions,judge_model:judgeModel})});onCreated(value)}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <Drawer title="New experiment" onClose={onClose}><div className="space-y-6 p-5"><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="label">Suite</span><select value={suiteID} onChange={e=>{setSuiteID(e.target.value);setJudgeModel(suites.find(x=>x.id===e.target.value)?.judge_model||"")}} className="field">{suites.map(x=><option key={x.id} value={x.id}>{x.name} · {x.cases?.length||0} cases</option>)}</select></label><label className="space-y-1"><span className="label">Repetitions</span><input type="number" min={1} max={20} value={repetitions} onChange={e=>setRepetitions(Number(e.target.value))} className="field"/></label></div><section className="space-y-3"><span className="label">Agent targets</span><SearchSelect placeholder="Search agents" items={catalog.agents} label={x=>`${x.name} · ${x.status}`} onSelect={setSelectedAgent}/>{selectedAgent&&<div className="rounded-md border border-border bg-bg-card p-3"><div className="mb-2 flex items-center justify-between"><span className="text-sm font-medium">{selectedAgent.name}</span><button onClick={()=>setSelectedAgent(null)} className="text-xs text-text-dim">Clear</button></div><SearchSelect placeholder="Search models" items={catalog.models} label={x=>x.display_name||modelID(x)} onSelect={addModel}/><button onClick={()=>{if(!targets.some(x=>x.agent_id===selectedAgent.id&&!x.model))setTargets([...targets,{agent_id:selectedAgent.id,agent_name:selectedAgent.name}])}} className="mt-2 text-xs text-accent">Use agent default model</button></div>}<div className="flex min-h-8 flex-wrap gap-1.5">{targets.length===0?<span className="text-xs text-text-dim">No targets selected</span>:targets.map((x,i)=><Chip key={`${x.agent_id}-${x.model}-${i}`} onRemove={()=>setTargets(targets.filter((_,j)=>j!==i))}>{x.agent_name} · {x.model||"default model"}</Chip>)}</div></section><label className="block space-y-1"><span className="label">Judge model</span><select value={judgeModel} onChange={e=>setJudgeModel(e.target.value)} className="field"><option value="">Deterministic checks only</option>{catalog.models.map(x=><option key={modelID(x)} value={modelID(x)}>{x.display_name||modelID(x)}</option>)}</select></label>{error&&<p className="rounded border border-red/40 bg-red/10 p-3 text-xs text-red">{error}</p>}</div><footer className="drawer-footer"><button onClick={onClose} className="button">Cancel</button><button disabled={busy||!suiteID||targets.length===0} onClick={create} className="button-primary">Run experiment</button></footer></Drawer>}

function SuiteEditor({initial,catalog,onClose,onSaved}:{initial?:Suite;catalog:Catalog;onClose:()=>void;onSaved:()=>void}){const [item,setItem]=useState<Partial<Suite>>(initial||{name:"",description:"",environment_id:"",judge_model:"",schedule_minutes:0,required_pass_rate:1,enabled:true,continuous_targets:[]});const [agent,setAgent]=useState<Agent|null>(null);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const save=async()=>{setBusy(true);try{await request(initial?`/suites/${initial.id}`:"/suites",{method:initial?"PUT":"POST",body:JSON.stringify(item)});onSaved();onClose()}catch(e:any){setError(e.message)}finally{setBusy(false)}};const targets=item.continuous_targets||[];const addTarget=(model?:Model)=>{if(!agent)return;const value={agent_id:agent.id,agent_name:agent.name,model:model?modelID(model):""};if(!targets.some(x=>x.agent_id===value.agent_id&&x.model===value.model))setItem({...item,continuous_targets:[...targets,value]})};return <Drawer title={initial?"Edit suite":"New suite"} onClose={onClose}><div className="space-y-5 p-5"><label className="block space-y-1"><span className="label">Name</span><input autoFocus value={item.name||""} onChange={e=>setItem({...item,name:e.target.value})} className="field"/></label><label className="block space-y-1"><span className="label">Description</span><textarea rows={2} value={item.description||""} onChange={e=>setItem({...item,description:e.target.value})} className="field"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="label">Environment</span><select value={item.environment_id||""} onChange={e=>setItem({...item,environment_id:e.target.value})} className="field"><option value="">Empty isolated runtime</option>{catalog.environments.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="space-y-1"><span className="label">Judge model</span><select value={item.judge_model||""} onChange={e=>setItem({...item,judge_model:e.target.value})} className="field"><option value="">Deterministic only</option>{catalog.models.map(x=><option key={modelID(x)} value={modelID(x)}>{x.display_name||modelID(x)}</option>)}</select></label></div><section className="space-y-3 border-t border-border pt-5"><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="label">Continuous interval</span><select value={item.schedule_minutes||0} onChange={e=>setItem({...item,schedule_minutes:Number(e.target.value)})} className="field"><option value={0}>Manual only</option><option value={60}>Hourly</option><option value={360}>Every 6 hours</option><option value={1440}>Daily</option><option value={10080}>Weekly</option></select></label><label className="space-y-1"><span className="label">Required pass rate</span><input type="number" min={0} max={100} value={Math.round((item.required_pass_rate||0)*100)} onChange={e=>setItem({...item,required_pass_rate:Number(e.target.value)/100})} className="field"/></label></div>{(item.schedule_minutes||0)>0&&<><span className="label">Continuous targets</span><SearchSelect placeholder="Search agents" items={catalog.agents} label={x=>x.name} onSelect={setAgent}/>{agent&&<div className="rounded-md border border-border bg-bg-card p-3"><div className="mb-2 text-sm font-medium">{agent.name}</div><SearchSelect placeholder="Add model target" items={catalog.models} label={x=>x.display_name||modelID(x)} onSelect={x=>addTarget(x)}/><button onClick={()=>addTarget()} className="mt-2 text-xs text-accent">Use default model</button></div>}<div className="flex flex-wrap gap-1.5">{targets.map((x,i)=><Chip key={i} onRemove={()=>setItem({...item,continuous_targets:targets.filter((_,j)=>j!==i)})}>{x.agent_name} · {x.model||"default"}</Chip>)}</div></>}</section><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={item.enabled!==false} onChange={e=>setItem({...item,enabled:e.target.checked})}/>Enabled</label>{error&&<p className="rounded border border-red/40 bg-red/10 p-3 text-xs text-red">{error}</p>}</div><footer className="drawer-footer"><button onClick={onClose} className="button">Cancel</button><button disabled={busy||!item.name} onClick={save} className="button-primary">Save suite</button></footer></Drawer>}

function CaseEditor({suite,initial,onClose,onSaved}:{suite:Suite;initial?:EvalCase;onClose:()=>void;onSaved:()=>void}){const [item,setItem]=useState<Partial<EvalCase>>(initial||{suite_id:suite.id,name:"",prompt:"",goals:[""],assertions:[],timeout_seconds:600,max_turns:10,enabled:true});const [assertionRaw,setAssertionRaw]=useState(JSON.stringify(initial?.assertions||[],null,2));const [error,setError]=useState("");const save=async()=>{try{let assertions:Assertion[];try{assertions=JSON.parse(assertionRaw)}catch{throw new Error("Assertions must be valid JSON")};await request(initial?`/cases/${initial.id}`:"/cases",{method:initial?"PUT":"POST",body:JSON.stringify({...item,suite_id:suite.id,assertions})});onSaved();onClose()}catch(e:any){setError(e.message)}};return <Drawer title={initial?"Edit case":"New case"} onClose={onClose}><div className="space-y-5 p-5"><label className="block space-y-1"><span className="label">Name</span><input autoFocus value={item.name||""} onChange={e=>setItem({...item,name:e.target.value})} className="field"/></label><label className="block space-y-1"><span className="label">Task</span><textarea rows={5} value={item.prompt||""} onChange={e=>setItem({...item,prompt:e.target.value})} className="field"/></label><label className="block space-y-1"><span className="label">Goals</span><textarea rows={4} value={(item.goals||[]).join("\n")} onChange={e=>setItem({...item,goals:e.target.value.split("\n")})} className="field"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="space-y-1"><span className="label">Max turns</span><input type="number" min={1} max={100} value={item.max_turns||10} onChange={e=>setItem({...item,max_turns:Number(e.target.value)})} className="field"/></label><label className="space-y-1"><span className="label">Timeout seconds</span><input type="number" min={5} max={1800} value={item.timeout_seconds||600} onChange={e=>setItem({...item,timeout_seconds:Number(e.target.value)})} className="field"/></label></div><label className="block space-y-1"><span className="label">Deterministic assertions</span><textarea rows={9} value={assertionRaw} onChange={e=>setAssertionRaw(e.target.value)} spellCheck={false} className="field font-mono text-xs"/></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={item.enabled!==false} onChange={e=>setItem({...item,enabled:e.target.checked})}/>Enabled</label>{error&&<p className="rounded border border-red/40 bg-red/10 p-3 text-xs text-red">{error}</p>}</div><footer className="drawer-footer"><button onClick={onClose} className="button">Cancel</button><button onClick={save} disabled={!item.name||!item.prompt} className="button-primary">Save case</button></footer></Drawer>}

function Drawer({title,onClose,children}:{title:string;onClose:()=>void;children:any}){return <div className="fixed inset-0 z-40 flex justify-end bg-black/50"><div className="flex h-full w-full max-w-2xl flex-col border-l border-border bg-bg shadow-2xl"><header className="flex h-14 shrink-0 items-center justify-between border-b border-border px-5"><h2 className="text-sm font-semibold">{title}</h2><button onClick={onClose} title="Close" className="h-8 w-8 text-xl text-text-dim hover:text-text">×</button></header><div className="flex min-h-0 flex-1 flex-col overflow-y-auto">{children}</div></div></div>}

function RunInspector({run,onClose}:{run:EvalRun;onClose:()=>void}){const trace=run.execution?.trace||[];const [suggestions,setSuggestions]=useState(run.suggestions||[]);const [error,setError]=useState("");const apply=async(id:string)=>{try{await request(`/suggestions/${id}/apply`,{method:"POST"});setSuggestions(suggestions.map(x=>x.id===id?{...x,status:"applied"}:x))}catch(e:any){setError(e.message)}};return <Drawer title={`${run.case.name} · ${run.target.agent_name||run.target.agent_id}`} onClose={onClose}><div className="space-y-5 p-5"><div className="grid grid-cols-3 overflow-hidden rounded-md border border-border"><Metric label="Result" value={run.status}/><Metric label="Score" value={score(run.overall_score)}/><Metric label="Turns" value={String(run.execution?.turns||0)}/></div>{(run.error||error)&&<p className="rounded border border-red/40 bg-red/10 p-3 text-xs text-red">{run.error||error}</p>}<section><h3 className="section-title">Assertions</h3>{run.assertions?.length?<div className="divide-y divide-border rounded-md border border-border">{run.assertions.map((x:any,i)=><div key={i} className="flex items-start gap-3 px-3 py-2"><span className={x.passed?"text-green":"text-red"}>{x.passed?"✓":"×"}</span><div><div className="text-sm">{x.name||`Assertion ${i+1}`}</div><div className="text-xs text-text-dim">{x.message}</div></div></div>)}</div>:<p className="text-xs text-text-dim">No deterministic assertions</p>}</section>{run.judge&&<section><h3 className="section-title">Judge</h3><div className="rounded-md border border-border p-3"><div className="mb-2 flex items-center justify-between"><Status value={run.judge.passed?"pass":"fail"}/><span className="text-sm font-semibold">{score(run.judge.score)}</span></div><p className="text-sm text-text-muted">{run.judge.reasoning}</p></div></section>}{suggestions.map(item=><section key={item.id}><h3 className="section-title">Directive suggestion</h3><div className="rounded-md border border-border p-3"><p className="mb-2 text-xs text-text-dim">{item.reason}</p><pre className="max-h-48 overflow-auto whitespace-pre-wrap rounded bg-bg-card p-2 text-xs">{item.directive}</pre><div className="mt-3 flex justify-end"><button disabled={item.status!=="proposed"} onClick={()=>apply(item.id)} className="button-primary">{item.status==="applied"?"Applied":"Apply directive"}</button></div></div></section>)}<section><h3 className="section-title">Trajectory</h3><div className="divide-y divide-border rounded-md border border-border">{trace.length===0?<Empty>No trace recorded</Empty>:trace.map(event=><div key={event.index} className="px-3 py-2"><div className="mb-1 text-[10px] font-semibold uppercase text-text-dim">{event.role}</div>{event.content&&<p className="whitespace-pre-wrap text-xs text-text">{event.content}</p>}{event.tool_call&&<div><code className="text-xs text-accent">{event.tool_call.name}</code>{event.tool_call.input&&<pre className="mt-1 max-h-32 overflow-auto whitespace-pre-wrap rounded bg-bg-card p-2 text-[10px] text-text-dim">{typeof event.tool_call.input==="string"?event.tool_call.input:JSON.stringify(event.tool_call.input,null,2)}</pre>}{event.tool_call.output&&<pre className={`mt-1 max-h-40 overflow-auto whitespace-pre-wrap rounded p-2 text-[10px] ${event.tool_call.is_error?"bg-red/10 text-red":"bg-bg-card text-text-dim"}`}>{event.tool_call.output}</pre>}</div>}</div>)}</div></section></div></Drawer>}

function ExperimentDetail({experiment,onRun}:{experiment:Experiment;onRun:(r:EvalRun)=>void}){const summary=experiment.summary;const runs=experiment.runs||[];return <section className="mt-5 border-t border-border pt-5"><header className="mb-3 flex items-center justify-between"><div><h2 className="text-base font-semibold">{experiment.name}</h2><p className="text-xs text-text-dim">{experiment.id} · {experiment.trigger_type}</p></div><Status value={experiment.status}/></header><div className="grid grid-cols-2 overflow-hidden rounded-md border border-border sm:grid-cols-5"><Metric label="Pass rate" value={pct(summary?.pass_rate||0)}/><Metric label="Score" value={score(summary?.average_score)}/><Metric label="Passed" value={String(summary?.passed||0)}/><Metric label="Failed" value={String((summary?.failed||0)+(summary?.errors||0))}/><Metric label="In progress" value={String((summary?.queued||0)+(summary?.running||0))}/></div>{summary?.targets?.length?<div className="mt-4 overflow-hidden rounded-md border border-border"><div className="grid grid-cols-[minmax(180px,1fr)_90px_90px_110px_100px] gap-3 border-b border-border bg-bg-card px-3 py-2 text-[11px] font-semibold uppercase text-text-dim"><span>Target</span><span>Pass rate</span><span>Score</span><span>Tokens</span><span>Cost</span></div>{summary.targets.map(target=><div key={target.target_index} className="grid grid-cols-[minmax(180px,1fr)_90px_90px_110px_100px] gap-3 border-b border-border px-3 py-2 text-xs last:border-0"><span className="truncate"><b>{target.target.agent_name}</b> · {target.target.model||"default"}</span><span>{pct(target.pass_rate)}</span><span>{score(target.average_score)}</span><span>{Math.round(target.average_tokens).toLocaleString()}</span><span>${target.average_cost_usd.toFixed(4)}</span></div>)}</div>:null}<div className="mt-4 overflow-hidden rounded-md border border-border"><div className="grid grid-cols-[minmax(180px,1.4fr)_minmax(160px,1fr)_70px_70px_80px] gap-3 border-b border-border bg-bg-card px-3 py-2 text-[11px] font-semibold uppercase text-text-dim"><span>Case</span><span>Target</span><span>Repeat</span><span>Score</span><span>Status</span></div>{runs.map(run=><button key={run.id} onClick={()=>onRun(run)} className="grid w-full grid-cols-[minmax(180px,1.4fr)_minmax(160px,1fr)_70px_70px_80px] gap-3 border-b border-border px-3 py-2 text-left text-xs last:border-0 hover:bg-bg-hover"><span className="truncate">{run.case.name}</span><span className="truncate">{run.target.agent_name} · {run.target.model||"default"}</span><span>{run.repetition}</span><span>{score(run.overall_score)}</span><Status value={run.status}/></button>)}</div></section>}

export default function EvalsPanel(props:NativePanelProps){installID=props.installId;projectID=props.projectId;const [tab,setTab]=useState<"experiments"|"suites">("experiments");const [suites,setSuites]=useState<Suite[]>([]);const [experiments,setExperiments]=useState<Experiment[]>([]);const [catalog,setCatalog]=useState<Catalog>({agents:[],models:[],environments:[]});const [selected,setSelected]=useState("");const [builder,setBuilder]=useState<string|null>(null);const [suiteEditor,setSuiteEditor]=useState<Suite|true|null>(null);const [caseEditor,setCaseEditor]=useState<{suite:Suite;item?:EvalCase}|null>(null);const [inspected,setInspected]=useState<EvalRun|null>(null);const [error,setError]=useState("");const load=useCallback(async()=>{try{const [suiteRows,expRows,cat]=await Promise.all([request<Suite[]>("/suites"),request<Experiment[]>("/experiments"),request<Catalog>("/catalog")]);setSuites(suiteRows);setExperiments(expRows);setCatalog(cat);if(!selected&&expRows[0])setSelected(expRows[0].id);setError("")}catch(e:any){setError(e.message)}},[selected]);useEffect(()=>{load();const timer=setInterval(load,3000);return()=>clearInterval(timer)},[load]);const selectedSummary=experiments.find(x=>x.id===selected);const [detail,setDetail]=useState<Experiment|null>(null);useEffect(()=>{if(!selected){setDetail(null);return}request<Experiment>(`/experiments/${selected}`).then(setDetail).catch(e=>setError(e.message))},[selected,experiments.find(x=>x.id===selected)?.status,experiments.find(x=>x.id===selected)?.summary?.queued]);return <div className="h-full overflow-auto bg-bg text-text"><style>{`.label{display:block;font-size:11px;font-weight:600;text-transform:uppercase;color:var(--color-text-dim)}.field{width:100%;border:1px solid var(--color-border);border-radius:6px;background:var(--color-bg-card);padding:8px 10px;font-size:14px;color:var(--color-text);outline:none}.field:focus{border-color:var(--color-accent)}.button{border:1px solid var(--color-border);border-radius:6px;padding:7px 12px;font-size:13px}.button-primary{border-radius:6px;background:var(--color-accent);color:var(--color-bg);padding:8px 13px;font-size:13px;font-weight:600}.button-primary:disabled{opacity:.4}.drawer-footer{display:flex;justify-content:flex-end;gap:8px;border-top:1px solid var(--color-border);padding:12px 20px}.section-title{margin-bottom:8px;font-size:11px;font-weight:600;text-transform:uppercase;color:var(--color-text-dim)}`}</style><div className="w-full p-5"><header className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h1 className="text-xl font-semibold">Evals</h1><div className="mt-2 flex gap-4"><button onClick={()=>setTab("experiments")} className={`border-b-2 pb-1 text-sm ${tab==="experiments"?"border-accent text-text":"border-transparent text-text-dim"}`}>Experiments</button><button onClick={()=>setTab("suites")} className={`border-b-2 pb-1 text-sm ${tab==="suites"?"border-accent text-text":"border-transparent text-text-dim"}`}>Suites</button></div></div><button onClick={()=>tab==="experiments"?setBuilder(suites[0]?.id||""):setSuiteEditor(true)} className="button-primary">{tab==="experiments"?"New experiment":"New suite"}</button></header>{error&&<div className="mb-4 flex items-center justify-between rounded-md border border-red/40 bg-red/10 px-3 py-2 text-xs text-red"><span>{error}</span><button onClick={()=>setError("")} title="Dismiss">×</button></div>}{tab==="experiments"?<>{experiments.length===0?<div className="rounded-md border border-border"><Empty>No experiments yet</Empty></div>:<div className="overflow-hidden rounded-md border border-border"><div className="hidden grid-cols-[minmax(200px,1fr)_110px_90px_90px_150px] gap-3 border-b border-border bg-bg-card px-3 py-2 text-[11px] font-semibold uppercase text-text-dim sm:grid"><span>Experiment</span><span>Progress</span><span>Pass rate</span><span>Score</span><span>Created</span></div>{experiments.map(exp=><button key={exp.id} onClick={()=>setSelected(exp.id)} className={`grid w-full grid-cols-1 gap-1 border-b border-border px-3 py-3 text-left last:border-0 hover:bg-bg-hover sm:grid-cols-[minmax(200px,1fr)_110px_90px_90px_150px] sm:items-center sm:gap-3 ${selected===exp.id?"bg-bg-card":""}`}><span className="min-w-0"><span className="block truncate text-sm font-medium">{exp.name}</span><span className="block truncate text-xs text-text-dim">{exp.targets.length} targets · {exp.repetitions} repetitions</span></span><Status value={exp.status}/><span className="text-xs">{pct(exp.summary?.pass_rate||0)}</span><span className="text-xs">{score(exp.summary?.average_score)}</span><span className="text-xs text-text-dim">{new Date(exp.created_at).toLocaleString()}</span></button>)}</div>}{detail&&selectedSummary&&<ExperimentDetail experiment={detail} onRun={setInspected}/>}</>:<div className="overflow-hidden rounded-md border border-border">{suites.length===0?<Empty>No suites yet</Empty>:suites.map(suite=><div key={suite.id} className="border-b border-border last:border-0"><div className="flex flex-col gap-3 px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><div className="flex items-center gap-2"><span className="truncate text-sm font-medium">{suite.name}</span>{suite.schedule_minutes>0&&<span className="rounded border border-border px-1.5 py-0.5 text-[10px] text-text-dim">every {suite.schedule_minutes}m</span>}</div><div className="text-xs text-text-dim">{suite.cases.length} cases · {catalog.environments.find(x=>x.id===suite.environment_id)?.name||"empty environment"} · revision {suite.revision}</div></div><div className="flex gap-2"><button onClick={()=>setCaseEditor({suite})} className="button">Add case</button><button onClick={()=>setSuiteEditor(suite)} className="button">Edit</button><button onClick={()=>{setTab("experiments");setBuilder(suite.id)}} className="button-primary">Run</button></div></div>{suite.cases.length>0&&<div className="border-t border-border bg-bg-card/40 px-4"><div className="divide-y divide-border">{suite.cases.map(item=><button key={item.id} onClick={()=>setCaseEditor({suite,item})} className="flex w-full items-center justify-between py-2 text-left"><span><span className="block text-xs font-medium">{item.name}</span><span className="block max-w-3xl truncate text-xs text-text-dim">{item.prompt}</span></span><span className="text-xs text-text-dim">{item.goals.length} goals · {item.assertions.length} checks</span></button>)}</div></div>}</div>)}</div>}</div>{builder!==null&&<ExperimentBuilder initialSuiteID={builder} suites={suites} catalog={catalog} onClose={()=>setBuilder(null)} onCreated={value=>{setBuilder(null);setSelected(value.id);load()}}/>}{suiteEditor&&<SuiteEditor initial={suiteEditor===true?undefined:suiteEditor} catalog={catalog} onClose={()=>setSuiteEditor(null)} onSaved={load}/>} {caseEditor&&<CaseEditor suite={caseEditor.suite} initial={caseEditor.item} onClose={()=>setCaseEditor(null)} onSaved={load}/>} {inspected&&<RunInspector run={inspected} onClose={()=>setInspected(null)}/>}</div>}
